response:
**Gates before launch.** First I run `git log -- spe/predictions/r04.yaml spe/plans/r04.md`. It must show both files in a commit, and neither file may have an uncommitted edit. Next comes the grader selftest. grade.py must score the oracle (answers.json passed in as predictions) at 100%. It must fail an empty answer file and a file with every label wrong. I also sanity-check judge.md on 2 replies I know are good and 2 I know are bad. Then I regrade the r03 results with the r04 grade.py to get a control. If the r03 numbers move, the grader changed, and I write that down before any trial runs. Last, I do a dry run with `args = {only: ['B:<ticket>', 'C2:<ticket>', 'C2:<ticket2>'], trials: 1}`. In that run I check four things: setup counts, valid schema output, check_status present in C2 only, and the spend log. When all gates pass, I commit `SPE r04 evaluate (harness): ...` locally and launch. I wrote this script without reading r03-workflow.js. The config paths, the tool simulator command, and the per-call cost estimates are defaults I made up. Copy the real values from r03's arguments. The dry run fails loudly if they are wrong. Both trials and judge run on Opus, so no judge from a different model family checks the tone grades.

```js
export const meta = {
  name: 'spe-support-triage-eval',
  description: 'SPE Evaluate round for the support triage agent. Configs B (12-line prompt, 6 tools) and C2 (12-line prompt, 3 tools plus check_status). 50 tickets, 5 trials per cell. Code grader checks label.category and label.priority. Opus judge grades reply tone. Spend cap comes from args.',
  phases: [
    { title: 'Setup' },
    { title: 'Trials' },
    { title: 'Audit' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Top-up' },
    { title: 'Synthesis' },
  ],
}

// ---------------- Arguments ----------------
const A = typeof args === 'object' && args ? args : {}
const ROUND = Number(A.round ?? 4)
const RR = `r${String(ROUND).padStart(2, '0')}`
const PREV = `r${String(ROUND - 1).padStart(2, '0')}`
const TRIALS = Number(A.trials ?? 5)
const EXPECT_TICKETS = Number(A.expectTickets ?? 50)
const ONLY = Array.isArray(A.only) ? new Set(A.only) : null // cell ids like 'B:T007'
const CAP_USD = Number(A.spendCapUsd ?? 40)
const SYNTH_RESERVE_USD = Number(A.synthesisReserveUsd ?? 3)
// Unmeasured estimates. Replace them with r03's measured per-call cost.
const EST = { setup: 0.2, trial: 0.05, audit: 0.3, gradeBatch: 0.1, judgeBatch: 0.12, synth: 1.5, ...(A.estUsd ?? {}) }
const TOPUP_PER_CELL = Number(A.topUpPerCell ?? 5)
const TOPUP_MAX = Number(A.topUpMaxTotal ?? 100)
const GRADE_BATCH = Number(A.gradeBatchSize ?? 50)
const JUDGE_BATCH = Number(A.judgeBatchSize ?? 10)
const TRIAL_MODEL = A.trialModel ?? 'opus'
const JUDGE_MODEL = A.judgeModel ?? 'opus'
const SEED = Number(A.seed ?? 4242)
const TICKETS_PATH = A.ticketsPath ?? 'spe/evals/tasks/tickets.json'
const TOOL_CMD = A.toolCmd ?? 'python spe/sim/tools.py'
// Defaults are assumptions. Copy the real paths from r03's args.
const CONFIG_SOURCES = A.configs ?? [
  { id: 'B', promptPath: 'spe/configs/B/system.md', toolsPath: 'spe/configs/B/tools.json', expectTools: 6 },
  { id: 'C2', promptPath: 'spe/configs/C2/system.md', toolsPath: 'spe/configs/C2/tools.json', expectTools: 4, mustHaveTool: 'check_status' },
]
const FORBIDDEN = /spe\/(evals|predictions|plans)\//

// ---------------- State, budget, halt ----------------
const STATE = { reservedUsd: 0, halted: null, skipped: [], issues: [], audit: [] }

function halt(reason) {
  if (!STATE.halted) {
    STATE.halted = reason
    log(`HALT: ${reason}`)
  }
}

// Reserve estimated cost before each paid call. Runs synchronously, so parallel thunks cannot race.
function reserve(usd, what, opts = {}) {
  if (STATE.halted && !opts.synth) {
    STATE.skipped.push({ what, reason: `round halted: ${STATE.halted}` })
    return false
  }
  const ceiling = opts.synth ? CAP_USD : CAP_USD - SYNTH_RESERVE_USD
  if (STATE.reservedUsd + usd > ceiling) {
    STATE.skipped.push({ what, reason: `spend cap: $${STATE.reservedUsd.toFixed(2)} reserved, ceiling $${ceiling.toFixed(2)}` })
    if (!opts.synth) halt(`spend cap reached before ${what}`)
    return false
  }
  STATE.reservedUsd += usd
  return true
}

// ---------------- Helpers ----------------
const chunk = (xs, n) => { const out = []; for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n)); return out }
const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null)
function seededShuffle(xs, seed) {
  let s = seed >>> 0 || 1
  const a = xs.slice()
  for (let i = a.length - 1; i > 0; i--) {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0
    const j = s % (i + 1)
    ;[a[i], a[j]] = [a[j], a[i]]
  }
  return a
}
const errText = (e) => String(e?.message ?? e)

// ---------------- Schemas ----------------
const SETUP_SCHEMA = {
  type: 'object',
  required: ['tickets', 'configs', 'problems'],
  properties: {
    tickets: { type: 'array', items: { type: 'object', required: ['id', 'text'], properties: { id: { type: 'string' }, text: { type: 'string' } } } },
    configs: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'system_prompt', 'tools'],
        properties: {
          id: { type: 'string' },
          system_prompt: { type: 'string' },
          tools: { type: 'array', items: { type: 'object', required: ['name', 'description', 'input_schema'], properties: { name: { type: 'string' }, description: { type: 'string' }, input_schema: { type: 'string' } } } },
        },
      },
    },
    problems: { type: 'array', items: { type: 'string' } },
  },
}

const TRIAL_SCHEMA = {
  type: 'object',
  required: ['label', 'reply', 'tool_calls', 'tool_errors', 'tools_used', 'paths_read'],
  properties: {
    label: { type: 'object', required: ['category', 'priority'], properties: { category: { type: 'string' }, priority: { type: 'string' } } },
    reply: { type: 'string' },
    tool_calls: { type: 'integer' },
    tool_errors: { type: 'integer' },
    tools_used: { type: 'array', items: { type: 'string' } },
    tokens_estimate: { type: 'integer' },
    paths_read: { type: 'array', items: { type: 'string' } },
    note: { type: 'string' },
  },
}

const AUDIT_SCHEMA = {
  type: 'object',
  required: ['scanned', 'transcripts_found', 'peeked'],
  properties: {
    scanned: { type: 'boolean' },
    transcripts_found: { type: 'integer' },
    peeked: { type: 'array', items: { type: 'object', required: ['label', 'path'], properties: { label: { type: 'string' }, path: { type: 'string' } } } },
    notes: { type: 'string' },
  },
}

const GRADE_SCHEMA = {
  type: 'object',
  required: ['results', 'canary_oracle_pass', 'canary_wrong_pass', 'grader_errors'],
  properties: {
    results: { type: 'array', items: { type: 'object', required: ['id', 'category_ok', 'priority_ok'], properties: { id: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } } } },
    canary_oracle_pass: { type: 'boolean' },
    canary_wrong_pass: { type: 'boolean' },
    grader_errors: { type: 'array', items: { type: 'string' } },
  },
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: { type: 'array', items: { type: 'object', required: ['jid', 'tone_pass', 'score', 'reason'], properties: { jid: { type: 'string' }, tone_pass: { type: 'boolean' }, score: { type: 'integer', minimum: 1, maximum: 5 }, reason: { type: 'string' } } } },
  },
}

const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['prediction_vs_result', 'failure_clusters', 'next_round_proposals'],
  properties: {
    prediction_vs_result: { type: 'array', items: { type: 'object', required: ['metric', 'config', 'predicted', 'measured', 'within_error', 'grader_check'], properties: { metric: { type: 'string' }, config: { type: 'string' }, predicted: { type: 'string' }, measured: { type: 'string' }, within_error: { type: 'boolean' }, grader_check: { type: 'string' } } } },
    failure_clusters: { type: 'array', items: { type: 'object', required: ['id', 'description', 'configs', 'count', 'example_trial_ids'], properties: { id: { type: 'string' }, description: { type: 'string' }, configs: { type: 'array', items: { type: 'string' } }, count: { type: 'integer' }, example_trial_ids: { type: 'array', items: { type: 'string' } } } } },
    next_round_proposals: { type: 'array', items: { type: 'string' } },
  },
}

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'measured_nothing', 'gaps'],
  properties: { complete: { type: 'boolean' }, measured_nothing: { type: 'boolean' }, gaps: { type: 'array', items: { type: 'string' } } },
}

// ---------------- Prompts ----------------
function setupPrompt() {
  return `You prepare inputs for an evaluation harness. Read the files named below and return their contents in the schema.
Do not open spe/evals/tasks/answers.json. Do not open anything under spe/evals/graders/, spe/predictions/, or spe/plans/.

1. Tickets. Read ${TICKETS_PATH}. Return every ticket as {id, text}. The text holds the subject and body the customer wrote. Leave out every label, category, priority, expected answer, or note field, even if the file has one.
2. Configs. For each config below, read promptPath into system_prompt. Read toolsPath into tools. Each tool's input_schema is its JSON schema as a string.
3. Problems. Add one line to problems for each of these: a file is missing, the ticket count is not ${EXPECT_TICKETS}, a config's tool count differs from expectTools, a mustHaveTool is absent, or a ticket record holds an answer field.

Configs: ${JSON.stringify(CONFIG_SOURCES)}`
}

function trialPrompt(cfg, ticket) {
  const toolCmd = cfg.toolCmd ?? `${TOOL_CMD} --config ${cfg.id} --ticket ${ticket.id}`
  return `You are the customer support agent under test. Work the ticket below the way the system prompt tells you.

Rules for this run:
- Do not read, list, search, or open any file or directory. Everything you need is in this message.
- The only command you may run is the tool simulator: ${toolCmd} <tool_name> '<json arguments>'
- Call only the tools listed below. Count every tool call in tool_calls. Count every call that returned an error in tool_errors. List the distinct tool names you called in tools_used.
- List every file path you opened or ran in paths_read. If you opened none, return an empty list.
- Give your best estimate of the tokens you used in tokens_estimate.

<system_prompt>
${cfg.system_prompt}
</system_prompt>

<tools>
${JSON.stringify(cfg.tools, null, 2)}
</tools>

<ticket id="${ticket.id}">
${ticket.text}
</ticket>

Return label.category, label.priority, and the reply you would send the customer.`
}

function auditPrompt(labels) {
  return `You audit an evaluation run for answer key leaks. Scan the agent transcripts under ${A.transcriptDir}.
Find the transcripts whose agent label is in the list below. In each one, look for any tool call that touched a path matching spe/evals/, spe/predictions/, or spe/plans/. Tool calls include Read, Grep, Glob, and Bash commands such as cat, ls, grep, find, or python.
Do not open any file under those directories yourself.
Return the number of matching transcripts you found, and one entry per forbidden touch with the label and the path.

Labels: ${JSON.stringify(labels)}`
}

function gradePrompt(rows) {
  const t = rows[0].ticket
  return `You run the code grader for an evaluation. Do not judge any row by eye.
1. Read spe/evals/graders/grade.py to learn its input format and command line. Do not edit grade.py or spe/evals/tasks/answers.json.
2. Write the rows below to a temp file outside the repo (use mktemp), in the format grade.py expects.
3. Add 2 canary rows to that file. Canary CANARY_ORACLE copies ticket ${t}'s category and priority from answers.json exactly. Canary CANARY_WRONG uses ticket ${t} with category "zz_not_a_category" and priority "zz_not_a_priority".
4. Run grade.py once on the file. Return its verdict for every row id, plus whether each canary passed.
5. If grade.py errors, or a row is missing from its output, put the message in grader_errors. Do not fill in a verdict yourself.

Rows: ${JSON.stringify(rows)}`
}

function judgePrompt(items) {
  return `You grade customer support replies for tone. Read spe/evals/graders/judge.md and apply its rubric exactly.
Judge only tone as judge.md defines it. Do not judge whether the labels or facts are right. You do not know which configuration wrote each reply, so do not guess.
Return one score per item, keyed by jid, with tone_pass, score, and a reason of one sentence.

Items: ${JSON.stringify(items)}`
}

// ---------------- Stages ----------------
async function runTrial(cfg, ticket, k, phaseName) {
  const id = `${cfg.id}:${ticket.id}:${k}`
  if (!reserve(EST.trial, `trial ${id}`)) return null
  const t0 = Date.now()
  try {
    const r = await agent(trialPrompt(cfg, ticket), { label: `trial ${id}`, phase: phaseName, schema: TRIAL_SCHEMA, model: TRIAL_MODEL })
    return { id, cfg: cfg.id, ticket: ticket.id, k, ms: Date.now() - t0, ok: true, ...r }
  } catch (e) {
    // Harness error or rate limit. Not a model failure. Excluded from metrics.
    return { id, cfg: cfg.id, ticket: ticket.id, k, ms: Date.now() - t0, ok: false, harnessError: errText(e) }
  }
}

async function audit(trials, phaseName) {
  const done = trials.filter((t) => t.ok)
  for (const t of done) {
    const hit = (t.paths_read ?? []).find((p) => FORBIDDEN.test(p))
    if (hit) t.voided = `self-reported read of ${hit}`
  }
  if (!A.transcriptDir) {
    const msg = `${phaseName}: no args.transcriptDir, so the transcript scan did not run. Only self-reports were checked.`
    log(msg)
    STATE.audit.push({ phase: phaseName, scanned: false, note: msg })
  } else if (done.length && reserve(EST.audit, `audit ${phaseName}`)) {
    try {
      const r = await agent(auditPrompt(done.map((t) => `trial ${t.id}`)), { label: `audit ${phaseName}`, phase: 'Audit', schema: AUDIT_SCHEMA, model: 'opus' })
      STATE.audit.push({ phase: phaseName, scanned: r.scanned, transcripts_found: r.transcripts_found, expected: done.length, notes: r.notes ?? '' })
      if (r.transcripts_found < done.length) STATE.issues.push(`${phaseName} audit found ${r.transcripts_found} of ${done.length} transcripts`)
      const byLabel = new Map(done.map((t) => [`trial ${t.id}`, t]))
      for (const p of r.peeked) {
        const t = byLabel.get(p.label)
        if (t) t.voided = `transcript read of ${p.path}`
      }
    } catch (e) {
      STATE.issues.push(`${phaseName} audit agent error: ${errText(e)}`)
    }
  }
  const voided = done.filter((t) => t.voided)
  if (voided.length) halt(`answer key leak: ${voided.length} trial(s) touched spe/evals, spe/predictions, or spe/plans (${voided.map((t) => t.id).join(', ')})`)
}

async function grade(trials, phaseName) {
  const rows = trials
    .filter((t) => t.ok && !t.voided && !t.grade)
    .map((t) => ({ id: t.id, ticket: t.ticket, category: t.label?.category ?? '', priority: t.label?.priority ?? '' }))
  const batches = chunk(rows, GRADE_BATCH)
  const outs = await parallel(
    batches.map((b, i) => async () => {
      if (!reserve(EST.gradeBatch, `grade ${phaseName} batch ${i}`)) return null
      try {
        return { b, r: await agent(gradePrompt(b), { label: `grade ${phaseName} ${i}`, phase: 'Grade', schema: GRADE_SCHEMA, model: 'opus' }) }
      } catch (e) {
        return { b, err: errText(e) }
      }
    }),
  )
  const byId = new Map(trials.map((t) => [t.id, t]))
  for (const o of outs) {
    if (!o) continue
    if (o.err) { STATE.issues.push(`grade agent error (harness, batch left ungraded): ${o.err}`); continue }
    const r = o.r
    if (!r.canary_oracle_pass || r.canary_wrong_pass || r.grader_errors.length) {
      halt(`grader broken: oracle canary pass=${r.canary_oracle_pass}, wrong canary pass=${r.canary_wrong_pass}, errors=${r.grader_errors.join('; ')}`)
      continue
    }
    const got = new Map(r.results.map((x) => [x.id, x]))
    const missing = o.b.filter((x) => !got.has(x.id))
    if (missing.length) { halt(`grader broken: ${missing.length} rows missing from grade.py output`); continue }
    for (const x of r.results) {
      const t = byId.get(x.id)
      if (t) t.grade = { category_ok: x.category_ok, priority_ok: x.priority_ok, both_ok: x.category_ok && x.priority_ok }
    }
  }
}

async function judge(trials, ticketText, phaseName) {
  const todo = seededShuffle(trials.filter((t) => t.ok && !t.voided && !t.tone), SEED + trials.length)
  const items = todo.map((t, i) => ({ jid: `J${String(i).padStart(4, '0')}`, trial: t }))
  const batches = chunk(items, JUDGE_BATCH)
  await parallel(
    batches.map((b, i) => async () => {
      if (!reserve(EST.judgeBatch, `judge ${phaseName} batch ${i}`)) return
      try {
        // The judge sees the ticket and the reply only. No config, no label, no trial id.
        const r = await agent(judgePrompt(b.map((x) => ({ jid: x.jid, ticket: ticketText.get(x.trial.ticket), reply: x.trial.reply }))), {
          label: `judge ${phaseName} ${i}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL,
        })
        const got = new Map(r.scores.map((s) => [s.jid, s]))
        for (const x of b) {
          const s = got.get(x.jid)
          if (s) x.trial.tone = { tone_pass: s.tone_pass, score: s.score, reason: s.reason }
          else STATE.issues.push(`judge skipped ${x.trial.id}`)
        }
      } catch (e) {
        STATE.issues.push(`judge agent error (harness, batch left unjudged): ${errText(e)}`)
      }
    }),
  )
}

function cellTable(trials) {
  const cells = new Map()
  for (const t of trials) {
    const key = `${t.cfg}:${t.ticket}`
    if (!cells.has(key)) cells.set(key, { cell: key, cfg: t.cfg, ticket: t.ticket, attempted: 0, completed: 0, graded: 0, passes: 0, tone_passes: 0, maxK: 0 })
    const c = cells.get(key)
    c.attempted++
    c.maxK = Math.max(c.maxK, t.k)
    if (t.ok && !t.voided) {
      c.completed++
      if (t.grade) { c.graded++; if (t.grade.both_ok) c.passes++ }
      if (t.tone?.tone_pass) c.tone_passes++
    }
  }
  return [...cells.values()]
}

function summarize(trials, cfgIds) {
  const out = {}
  for (const id of cfgIds) {
    const all = trials.filter((t) => t.cfg === id)
    const done = all.filter((t) => t.ok && !t.voided)
    const graded = done.filter((t) => t.grade)
    const judged = done.filter((t) => t.tone)
    out[id] = {
      attempted: all.length,
      completed: done.length,
      harness_errors: all.filter((t) => !t.ok).length,
      voided: all.filter((t) => t.voided).length,
      graded: graded.length,
      judged: judged.length,
      category_acc: mean(graded.map((t) => (t.grade.category_ok ? 1 : 0))),
      priority_acc: mean(graded.map((t) => (t.grade.priority_ok ? 1 : 0))),
      both_acc: mean(graded.map((t) => (t.grade.both_ok ? 1 : 0))),
      tone_pass_rate: mean(judged.map((t) => (t.tone.tone_pass ? 1 : 0))),
      tone_mean_score: mean(judged.map((t) => t.tone.score)),
      mean_runtime_s: mean(done.map((t) => t.ms / 1000)),
      mean_tool_calls: mean(done.map((t) => t.tool_calls)),
      mean_tool_errors: mean(done.map((t) => t.tool_errors)),
      mean_tokens_self_reported: mean(done.filter((t) => Number.isFinite(t.tokens_estimate)).map((t) => t.tokens_estimate)),
      check_status_use_rate: mean(done.map((t) => ((t.tools_used ?? []).includes('check_status') ? 1 : 0))),
    }
  }
  return out
}

// ---------------- Setup ----------------
phase('Setup')
log(`${RR}: ${TRIALS} trials per cell, spend cap $${CAP_USD} with $${SYNTH_RESERVE_USD} held back for synthesis. Cost figures are unmeasured estimates.`)
if (!reserve(EST.setup, 'setup')) throw new Error('Setup could not reserve budget')
const setup = await agent(setupPrompt(), { label: 'setup', phase: 'Setup', schema: SETUP_SCHEMA, model: 'opus' })
const problems = [...setup.problems]
if (setup.tickets.length !== EXPECT_TICKETS) problems.push(`ticket count ${setup.tickets.length}, expected ${EXPECT_TICKETS}`)
for (const src of CONFIG_SOURCES) {
  const c = setup.configs.find((x) => x.id === src.id)
  if (!c) { problems.push(`config ${src.id} missing`); continue }
  if (src.expectTools && c.tools.length !== src.expectTools) problems.push(`config ${src.id} has ${c.tools.length} tools, expected ${src.expectTools}`)
  if (src.mustHaveTool && !c.tools.some((t) => t.name === src.mustHaveTool)) problems.push(`config ${src.id} lacks ${src.mustHaveTool}`)
  if (!src.mustHaveTool && c.tools.some((t) => t.name === 'check_status')) problems.push(`config ${src.id} unexpectedly has check_status`)
  if (src.toolCmd) c.toolCmd = src.toolCmd
}
for (const t of setup.tickets) if (/"(category|priority|answer|label)"\s*:/i.test(t.text)) problems.push(`ticket ${t.id} text looks like it holds an answer field`)
if (problems.length) throw new Error(`Setup gate failed: ${problems.join(' | ')}`)

const CONFIGS = CONFIG_SOURCES.map((s) => setup.configs.find((c) => c.id === s.id))
const ticketText = new Map(setup.tickets.map((t) => [t.id, t.text]))
const cells = []
for (const ticket of setup.tickets) for (const cfg of CONFIGS) {
  if (!ONLY || ONLY.has(`${cfg.id}:${ticket.id}`)) cells.push({ cfg, ticket })
}
log(`${cells.length} cells, ${cells.length * TRIALS} planned trials${ONLY ? ' (dry run subset)' : ''}`)

// ---------------- Trials ----------------
phase('Trials')
// k is the outer loop and configs alternate inside it, so a cap hit cuts both configs evenly.
const thunks = []
for (let k = 1; k <= TRIALS; k++) for (const c of cells) thunks.push(() => runTrial(c.cfg, c.ticket, k, 'Trials'))
const trials = (await parallel(thunks)).filter(Boolean)
log(`Trials done: ${trials.filter((t) => t.ok).length} completed, ${trials.filter((t) => !t.ok).length} harness errors`)

// ---------------- Audit, Grade, Judge ----------------
phase('Audit')
await audit(trials, 'main')
phase('Grade')
await grade(trials, 'main')
phase('Judge')
await judge(trials, ticketText, 'main')

// ---------------- Top-up ----------------
phase('Top-up')
const mixed = cellTable(trials).filter((c) => c.graded > 0 && c.passes > 0 && c.passes < c.graded)
let topUpBudget = TOPUP_MAX
const topThunks = []
for (let extra = 1; extra <= TOPUP_PER_CELL; extra++) {
  for (const c of mixed) {
    if (topUpBudget <= 0) break
    const cfg = CONFIGS.find((x) => x.id === c.cfg)
    const ticket = setup.tickets.find((x) => x.id === c.ticket)
    const k = c.maxK + extra
    topThunks.push(() => runTrial(cfg, ticket, k, 'Top-up'))
    topUpBudget--
  }
}
log(`Top-up: ${mixed.length} mixed cells, ${topThunks.length} extra trials queued (cap ${TOPUP_PER_CELL} per cell, ${TOPUP_MAX} total)`)
const topTrials = (await parallel(topThunks)).filter(Boolean)
trials.push(...topTrials)
if (topTrials.length) {
  await audit(topTrials, 'top-up')
  await grade(topTrials, 'top-up')
  await judge(topTrials, ticketText, 'top-up')
}

// ---------------- Synthesis ----------------
phase('Synthesis')
const cfgIds = CONFIGS.map((c) => c.id)
const summary = summarize(trials, cfgIds)
const table = cellTable(trials)
const failing = trials
  .filter((t) => t.ok && !t.voided && ((t.grade && !t.grade.both_ok) || (t.tone && !t.tone.tone_pass)))
  .slice(0, 150)
  .map((t) => ({ id: t.id, label: t.label, grade: t.grade, tone: t.tone, tools_used: t.tools_used, tool_errors: t.tool_errors, reply_start: (t.reply ?? '').slice(0, 300) }))
const spend = { reserved_usd: Number(STATE.reservedUsd.toFixed(2)), cap_usd: CAP_USD, note: 'Estimate from per-call reservations. This is not billed spend. Check billing before the results commit.' }
const facts = { round: ROUND, halted: STATE.halted, spend, summary, cells: table, skipped_count: STATE.skipped.length, skipped_sample: STATE.skipped.slice(0, 30), issues: STATE.issues, audit: STATE.audit, failing_sample: failing }

let analysis = null
if (reserve(EST.synth, 'failure analysis', { synth: true })) {
  try {
    analysis = await agent(
      `You analyze the results of SPE round ${ROUND}. You may read spe/predictions/${RR}.yaml, spe/plans/${RR}.md, spe/failures.md, spe/prediction-log.md, and the files under spe/evals/graders/ and spe/evals/tasks/. Do not write or edit any file. The Learn step writes the log later.
${STATE.halted ? `The round halted: ${STATE.halted}. Say what the halt means for which numbers can be trusted.` : ''}
1. For every predicted number in spe/predictions/${RR}.yaml, give the predicted value, the measured value, whether it falls within the stated error, and the grader check that measured it. If a prediction has no measurement, mark measured as "not measured".
2. Group the failures into clusters. Give each cluster an id, the configs it hits, a count, and example trial ids.
3. Say what round ${ROUND + 1} should change. Use the stop rules. If every config passed everything, propose harder tasks or stricter graders, not more trials.

Facts: ${JSON.stringify(facts)}`,
      { label: 'failure analysis', phase: 'Synthesis', schema: ANALYSIS_SCHEMA, model: 'opus' },
    )
  } catch (e) {
    STATE.issues.push(`failure analysis error: ${errText(e)}`)
  }
}

let critic = null
if (reserve(EST.synth, 'completeness critic', { synth: true })) {
  try {
    critic = await agent(
      `You are the completeness critic for SPE round ${ROUND}. Do not write or edit any file. You may read spe/predictions/${RR}.yaml.
Check each item and list every gap:
- Every cell has at least ${TRIALS} completed and graded trials, unless the cell was skipped by a logged cap or halt.
- Grader canaries passed in every grade batch. No grade batch was left ungraded.
- The transcript audit ran on every trial, or the report says plainly that it did not.
- Every completed trial has a tone grade.
- Every predicted metric in spe/predictions/${RR}.yaml has a measured value.
- Harness errors are excluded from accuracy, and the count is reported.
- The judge and the trials share a model family. Say so as a known limit.
Set measured_nothing to true if every config passed every check.
Set complete to true only if you found no gap that changes a headline number.

Facts: ${JSON.stringify({ ...facts, analysis })}`,
      { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: 'opus' },
    )
  } catch (e) {
    STATE.issues.push(`completeness critic error: ${errText(e)}`)
  }
}

log(`Done. Halted: ${STATE.halted ?? 'no'}. Reserved spend estimate: $${STATE.reservedUsd.toFixed(2)} of $${CAP_USD}.`)

// The main session writes this object to spe/evals/results/${RR}/ before the results commit.
return {
  round: ROUND,
  previous_round: PREV,
  halted: STATE.halted,
  spend,
  summary,
  cells: table,
  skipped: STATE.skipped,
  issues: STATE.issues,
  audit: STATE.audit,
  analysis,
  critic,
  trials,
}
